/**
 * 0.2.12 C11-5：把农历单一数据源同步到前后端。
 *
 *   code/shared/lunar.mjs  ──►  code/app/lib/lunar-core.mjs   （后端打包进 app/server）
 *                          ──►  code/web/src/js/lib/lunar-core.js（前端 vite 打进 bundle）
 *
 * 生成物带 AUTO-GENERATED 头注释；`tests/lunar-shared-0212.test.js` 与
 * `app/test/m8-0212-lunar.test.mjs` 都会断言之与源文件逐字一致，漂移即测试失败。
 *
 * 用法：
 *   node scripts/sync-lunar.mjs            # 写入
 *   node scripts/sync-lunar.mjs --check    # 只检查，漂移时 exit 1
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const codeRoot = join(here, '..');
const source = join(codeRoot, 'shared', 'lunar.mjs');
const targets = [
  join(codeRoot, 'app', 'lib', 'lunar-core.mjs'),
  join(codeRoot, 'web', 'src', 'js', 'lib', 'lunar-core.js'),
];
const HEADER = '/* AUTO-GENERATED by code/scripts/sync-lunar.mjs — 勿手改；源：code/shared/lunar.mjs */\n';

const body = readFileSync(source, 'utf8');
const expected = HEADER + body;
const check = process.argv.includes('--check');
let drift = 0;

for (const target of targets) {
  let current = null;
  try {
    current = readFileSync(target, 'utf8');
  } catch {
    current = null;
  }
  if (current === expected) {
    console.log(`[lunar] 一致 ${relative(codeRoot, target)}`);
    continue;
  }
  drift += 1;
  if (check) {
    console.log(`[lunar] 漂移 ${relative(codeRoot, target)}`);
    continue;
  }
  writeFileSync(target, expected, 'utf8');
  console.log(`[lunar] 已写入 ${relative(codeRoot, target)}`);
}

if (check && drift) {
  console.error(`[lunar] 有 ${drift} 个生成物与源文件不一致，请运行 node scripts/sync-lunar.mjs`);
  process.exit(1);
}
